import{_ as d,a0 as p,w as l,s,I as r,x as e,a1 as n,A as o,ao as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const c=JSON.parse('{"title":"如何在 CentOS 中設置 NTP 服務器 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 CentOS 中設置 NTP 服務器 | LCTT (201506) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 CentOS 中設置 NTP 服務器 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 CentOS 中設置 NTP 服務器 | LCTT (201506) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201506/20150427 How to set up NTP server in CentOS","title":"如何在 CentOS 中設置 NTP 服務器","tag":"201506","desc":""},"relativePath":"201506/20150427 How to set up NTP server in CentOS.md","filePath":"[post].md"}'),m={name:"201506/20150427 How to set up NTP server in CentOS.md"};function T(P,t,u,N,h,f){const a=p("Link");return l(),s("div",null,[t[18]||(t[18]=r("h1",{id:"如何在-centos-中設置-ntp-服務器",tabindex:"-1"},[e("如何在 CentOS 中設置 NTP 服務器 "),r("a",{class:"header-anchor",href:"#如何在-centos-中設置-ntp-服務器","aria-label":"Permalink to “如何在 CentOS 中設置 NTP 服務器”"},"​")],-1)),t[19]||(t[19]=r("p",null,"網絡時間協議(NTP)用來同步網絡上不同主機的系統時間。你管理的所有主機都可以和一個指定的被稱為 NTP 服務器的時間服務器同步它們的時間。而另一方面，一個 NTP 服務器會將它的時間和任意公共 NTP 服務器，或者你選定的服務器同步。由 NTP 管理的所有系統時鐘都會同步精確到毫秒級。",-1)),t[20]||(t[20]=r("p",null,"在公司環境中，如果他們不想為 NTP 傳輸打開防火牆，就有必要設置一個內部 NTP 服務器，然後讓員工使用內部服務器而不是公共 NTP 服務器。在這個指南中，我們會介紹如何將一個 CentOS 系統配置為 NTP 服務器。在介紹詳細內容之前，讓我們先來簡單瞭解一下 NTP 的概念。",-1)),t[21]||(t[21]=r("h3",{id:"為什麼我們需要-ntp",tabindex:"-1"},[e("為什麼我們需要 NTP? "),r("a",{class:"header-anchor",href:"#為什麼我們需要-ntp","aria-label":"Permalink to “為什麼我們需要 NTP?”"},"​")],-1)),t[22]||(t[22]=r("p",null,"由於製造工藝多種多樣，所有的(非原子)時鐘並不按照完全一致的速度行走。有一些時鐘走的比較快而有一些走的比較慢。因此經過很長一段時間以後，一個時鐘的時間慢慢的和其它的發生偏移，這就是常説的 “時鐘漂移” 或 “時間漂移”。為了將時鐘漂移的影響最小化，使用 NTP 的主機應該週期性地和指定的 NTP 服務器交互以保持它們的時鐘同步。",-1)),r("p",null,[t[2]||(t[2]=e("在不同的主機之間進行時間同步對於計劃備份、",-1)),n(a,{href:"http://xmodulo.com/how-to-compile-and-install-snort-from-source-code-on-ubuntu.html"},{default:o(()=>[...t[0]||(t[0]=[e("入侵檢測",-1)])]),_:1}),t[3]||(t[3]=e("記錄、",-1)),n(a,{href:"http://xmodulo.com/how-to-install-hdfs-and-hadoop-using.html"},{default:o(()=>[...t[1]||(t[1]=[e("分佈式任務調度",-1)])]),_:1}),t[4]||(t[4]=e("或者事務訂單管理來説是很重要的事情。它甚至應該作為日常任務的一部分。",-1))]),t[23]||(t[23]=i(`<h3 id="ntp-的層次結構" tabindex="-1">NTP 的層次結構 <a class="header-anchor" href="#ntp-的層次結構" aria-label="Permalink to “NTP 的層次結構”">​</a></h3><p>NTP 時鐘以層次模型組織。層級中的每層被稱為一個 <em>stratum（階層）</em>。stratum 的概念説明了一台機器到授權的時間源有多少 NTP 跳。</p><p><img src="https://farm8.staticflickr.com/7590/16645732413_3b7af58186_c.jpg" alt=""></p><p>Stratum 0 由沒有時間漂移的時鐘組成，例如原子時鐘。這種時鐘不能在網絡上直接使用。Stratum N (N &gt; 1) 層服務器從 Stratum N-1 層服務器同步時間。Stratum N 時鐘能通過網絡和彼此互聯。</p><p>NTP 支持多達 15 個 stratum 的層級。Stratum 16 被認為是未同步的，不能使用的。</p><h3 id="準備-centos-服務器" tabindex="-1">準備 CentOS 服務器 <a class="header-anchor" href="#準備-centos-服務器" aria-label="Permalink to “準備 CentOS 服務器”">​</a></h3><p>現在讓我們來開始在 CentOS 上設置 NTP 服務器。</p><p>首先，我們需要保證正確設置了服務器的時區。在 CentOS 7 中，我們可以使用 timedatectl 命令查看和更改服務器的時區(比如，&quot;Australia/Adelaide&quot;，LCTT 譯註：中國可設置為 Asia/Shanghai )</p><pre><code># timedatectl list-timezones | grep Australia
# timedatectl set-timezone Australia/Adelaide
# timedatectl
</code></pre><p><img src="https://farm8.staticflickr.com/7605/16645732463_db75a0bdcd_o.png" alt=""></p><p>繼續並使用 yum 安裝需要的軟件</p><pre><code># yum install ntp
</code></pre><p>然後我們會添加全球 NTP 服務器用於同步時間。</p><pre><code># vim /etc/ntp.conf
</code></pre><hr><pre><code>server 0.oceania.pool.ntp.org
server 1.oceania.pool.ntp.org
server 2.oceania.pool.ntp.org
server 3.oceania.pool.ntp.org
</code></pre><p>默認情況下，NTP 服務器的日誌保存在 /var/log/messages。如果你希望使用自定義的日誌文件，那也可以指定。</p><pre><code>logfile /var/log/ntpd.log
</code></pre><p>如果你選擇自定義日誌文件，確保更改了它的屬主和 SELinux 環境。</p><pre><code># chown ntp:ntp /var/log/ntpd.log
# chcon -t ntpd_log_t /var/log/ntpd.log
</code></pre><p>現在初始化 NTP 服務並確保把它添加到了開機啓動。</p><pre><code># systemctl restart ntp
# systemctl enable ntp
</code></pre><h3 id="驗證-ntp-server-時鐘" tabindex="-1">驗證 NTP Server 時鐘 <a class="header-anchor" href="#驗證-ntp-server-時鐘" aria-label="Permalink to “驗證 NTP Server 時鐘”">​</a></h3><p>我們可以使用 ntpq 命令來檢查本地服務器的時鐘如何通過 NTP 同步。</p><p><img src="https://farm9.staticflickr.com/8713/16645732513_1823736ca8_b.jpg" alt=""></p><p>下面的表格解釋了輸出列。</p><table id="content"><tbody><tr><td>remote</td><td>源在 ntp.conf 中定義。‘*’ 表示當前使用的，也是最好的源；‘+’ 表示這些源可作為 NTP 源；‘-’ 標記的源是不可用的。</td></tr><tr><td>refid</td><td>用於和本地時鐘同步的遠程服務器的 IP 地址。</td></tr><tr><td>st</td><td>Stratum（階層）</td></tr><tr><td>t</td><td>類型。 &#39;u&#39; 表示單播(unicast)。其它值包括本地(local)、多播(multicast)、廣播(broadcast)。</td></tr><tr><td>when</td><td>自從上次和服務器交互後經過的時間(以秒數計)。</td></tr><tr><td>poll</td><td>和服務器的輪詢間隔，以秒數計。</td></tr><tr><td>reach</td><td>表示和服務器交互是否有任何錯誤的八進制數。值 337 表示 100% 成功（即十進制的255）。</td></tr><tr><td>delay</td><td>服務器和遠程服務器來回的時間。</td></tr><tr><td>offset</td><td>我們服務器和遠程服務器的時間差異，以毫秒數計。</td></tr><tr><td>jitter</td><td>兩次取樣之間平均時差，以毫秒數計。</td></tr></tbody></table><h3 id="控制到-ntp-服務器的訪問" tabindex="-1">控制到 NTP 服務器的訪問 <a class="header-anchor" href="#控制到-ntp-服務器的訪問" aria-label="Permalink to “控制到 NTP 服務器的訪問”">​</a></h3><p>默認情況下，NTP 服務器允許來自所有主機的查詢。如果你想過濾進來的 NTP 同步連接，你可以在你的防火牆中添加規則過濾流量。</p><pre><code># iptables -A INPUT -s 192.168.1.0/24 -p udp --dport 123 -j ACCEPT
# iptables -A INPUT -p udp --dport 123 -j DROP
</code></pre><p>該規則允許從 192.168.1.0/24 來的 NTP 流量(端口 UDP/123)，任何其它網絡的流量會被丟棄。你可以根據需要更改規則。</p><h3 id="配置-ntp-客户端" tabindex="-1">配置 NTP 客户端 <a class="header-anchor" href="#配置-ntp-客户端" aria-label="Permalink to “配置 NTP 客户端”">​</a></h3><h4 id="_1-linux" tabindex="-1">1. Linux <a class="header-anchor" href="#_1-linux" aria-label="Permalink to “1. Linux”">​</a></h4><p>NTP 客户端主機需要 ntpupdate 軟件包來和服務器同步時間。可以輕鬆地使用 yum 或 apt-get 安裝這個軟件包。安裝完軟件包之後，用服務器的 IP 地址運行下面的命令。</p><pre><code># ntpdate &lt;server-IP-address&gt;
</code></pre><p>基於 RHEL 和 Debian 的系統命令都相同。</p><h4 id="_2-windows" tabindex="-1">2. Windows <a class="header-anchor" href="#_2-windows" aria-label="Permalink to “2. Windows”">​</a></h4><p>如果你正在使用 Windows，在日期和時間設置(Date and Time settings)下查找網絡時間(Internet Time)。</p><h4 id="_3-cisco-設備" tabindex="-1">3. Cisco 設備 <a class="header-anchor" href="#_3-cisco-設備" aria-label="Permalink to “3. Cisco 設備”">​</a></h4><p>如果你想要同步 Cisco 設備的時間，你可以在全局配置模式下使用下面的命令。</p><pre><code># ntp server &lt;server-IP-address&gt;
</code></pre><p>來自其它廠家的支持 NTP 的設備有自己的用於網絡時間的參數。如果你想將設備和 NTP服務器同步時間，請查看設備的説明文檔。</p><h3 id="結論" tabindex="-1">結論 <a class="header-anchor" href="#結論" aria-label="Permalink to “結論”">​</a></h3><p>總而言之，NTP 是在你的所有主機上同步時鐘的一個協議。我們已經介紹瞭如何設置 NTP 服務器並使支持 NTP 的設備和服務器同步時間。</p><p>希望能對你有所幫助。</p><hr>`,46)),r("p",null,[t[6]||(t[6]=e("via: ",-1)),n(a,{href:"http://xmodulo.com/setup-ntp-server-centos.html"},{default:o(()=>[...t[5]||(t[5]=[e("http://xmodulo.com/setup-ntp-server-centos.html",-1)])]),_:1})]),r("p",null,[t[10]||(t[10]=e("作者：",-1)),n(a,{href:"http://xmodulo.com/author/sarmed"},{default:o(()=>[...t[7]||(t[7]=[e("Sarmed Rahman",-1)])]),_:1}),t[11]||(t[11]=e(" 譯者：",-1)),n(a,{href:"https://github.com/ictlyh"},{default:o(()=>[...t[8]||(t[8]=[e("ictlyh",-1)])]),_:1}),t[12]||(t[12]=e(" 校對：",-1)),n(a,{href:"https://github.com/wxy"},{default:o(()=>[...t[9]||(t[9]=[e("wxy",-1)])]),_:1})]),r("p",null,[t[15]||(t[15]=e("本文由 ",-1)),n(a,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[13]||(t[13]=[e("LCTT",-1)])]),_:1}),t[16]||(t[16]=e(" 原創翻譯，",-1)),n(a,{href:"http://linux.cn/"},{default:o(()=>[...t[14]||(t[14]=[e("Linux中國",-1)])]),_:1}),t[17]||(t[17]=e(" 榮譽推出",-1))])])}const g=d(m,[["render",T]]);export{c as __pageData,g as default};
